-- POLIGRAFISTA/VISITADOR dejan de guardar sus ciudades como texto libre (sala_encargada,
-- zonas_visita) y pasan a una relación real contra el catálogo de ciudades: escalable a
-- "varias ciudades por empleado" y consultable para asignar servicios por ciudad.
CREATE TABLE "empleado_ciudades" (
  "id_empleado_ciudad" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_empleado" INTEGER NOT NULL,
  "id_ciudad" INTEGER NOT NULL,
  "numero_sala" INTEGER,
  CONSTRAINT "uq_empleado_ciudad_sala" UNIQUE ("id_empleado", "id_ciudad", "numero_sala"),
  FOREIGN KEY ("id_empleado") REFERENCES "empleados" ("id_empleado") ON DELETE CASCADE,
  FOREIGN KEY ("id_ciudad") REFERENCES "ciudades" ("id_ciudad")
);

CREATE INDEX "idx_empleado_ciudades_empleado" ON "empleado_ciudades" ("id_empleado");
CREATE INDEX "idx_empleado_ciudades_ciudad" ON "empleado_ciudades" ("id_ciudad");

-- Backfill best-effort desde el texto libre existente: sala_encargada = "Ciudad - Sala N"
-- (separado por comas), zonas_visita = nombres de ciudad separados por comas. Se casa por
-- nombre exacto (case-insensitive) contra el catálogo; lo que no calce queda sin migrar y el
-- admin lo vuelve a asignar desde el nuevo selector (ya no acepta texto libre).
DO $$
DECLARE
  emp RECORD;
  parte TEXT;
  m TEXT[];
  nombre_buscado TEXT;
  num_sala INTEGER;
  ciudad_id INTEGER;
BEGIN
  FOR emp IN SELECT id_empleado, sala_encargada, zonas_visita FROM empleados LOOP

    IF emp.sala_encargada IS NOT NULL AND btrim(emp.sala_encargada) <> '' THEN
      FOREACH parte IN ARRAY string_to_array(emp.sala_encargada, ',') LOOP
        parte := btrim(parte);
        CONTINUE WHEN parte = '';
        m := regexp_match(parte, '^(.*) - Sala (\d+)$');
        IF m IS NOT NULL THEN
          nombre_buscado := btrim(m[1]);
          num_sala := m[2]::INTEGER;
        ELSE
          nombre_buscado := parte;
          num_sala := NULL;
        END IF;

        SELECT id_ciudad INTO ciudad_id FROM ciudades
          WHERE lower(nombre_ciudad) = lower(nombre_buscado) LIMIT 1;

        IF ciudad_id IS NOT NULL THEN
          INSERT INTO empleado_ciudades (id_empleado, id_ciudad, numero_sala)
          VALUES (emp.id_empleado, ciudad_id, num_sala)
          ON CONFLICT DO NOTHING;
        END IF;
      END LOOP;
    END IF;

    IF emp.zonas_visita IS NOT NULL AND btrim(emp.zonas_visita) <> '' THEN
      FOREACH parte IN ARRAY string_to_array(emp.zonas_visita, ',') LOOP
        parte := btrim(parte);
        CONTINUE WHEN parte = '';

        SELECT id_ciudad INTO ciudad_id FROM ciudades
          WHERE lower(nombre_ciudad) = lower(parte) LIMIT 1;

        IF ciudad_id IS NOT NULL THEN
          INSERT INTO empleado_ciudades (id_empleado, id_ciudad, numero_sala)
          VALUES (emp.id_empleado, ciudad_id, NULL)
          ON CONFLICT DO NOTHING;
        END IF;
      END LOOP;
    END IF;

  END LOOP;
END $$;

ALTER TABLE "empleados" DROP COLUMN "sala_encargada";
ALTER TABLE "empleados" DROP COLUMN "zonas_visita";
